#include <iostream>
#include <vector>
using namespace std;

int n, m;
vector<int> G[100005];
char s[100005];
bool used[100005];
vector<int> ans;

void dfs(int v)
{
  used[v] = true;
  ans.push_back(v), s[v] ^= 1;
  for(auto u : G[v]){
    if(used[u]) continue;
    dfs(u);
    ans.push_back(v), s[v] ^= 1;
    if(s[u] == 1){
      ans.push_back(u), s[u] ^= 1;
      ans.push_back(v), s[v] ^= 1;
    }
  }
}

int main(void)
{
  cin >> n >> m;
  int u, v;
  for(int i = 1; i <= m; i++){
    cin >> u >> v;
    G[u].push_back(v);
    G[v].push_back(u);
  }
  for(int i = 1; i <= n; i++) cin >> s[i], s[i] -= '0';

  dfs(1);
  if(s[1] == 1){
    ans.push_back(G[1][0]);
    ans.push_back(1);
    ans.push_back(G[1][0]);
  }

  cout << ans.size() << endl;
  for(auto x : ans) cout << x << " ";
  cout << endl;

  return 0;
}
